export const factorySourceCopy = Object.fromEntries(Object.entries(factoryMessages).map(([language, messages]) => [language,
  Object.fromEntries(Object.entries(factoryMessages.de).map(([key, source]) => [source, messages[key]])),
]));

/** Interpolate supplied names and values literally; no word replacements. */
export function factoryText(key, values = {}, language = 'de') {
  const template = factoryMessages[language]?.[key] ?? factoryMessages.de[key] ?? key;
  return String(template).replace(/\{(\w+)\}/g, (match, name) => Object.hasOwn(values, name) && values[name] != null ? String(values[name]) : match);
}

export default factoryMessages;
